"use client";

import React, { useCallback, useEffect, useState } from "react";
import { Check, Copy, RefreshCw, Tag, Trash2 } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { formatDate } from "@/lib/utils";

/**
 * Admin → "Referral codes" tab.
 *
 * Codes are GENERATED by the server (`POST /api/admin/referral-codes` with no
 * body) — an administrator never has to invent one. A custom code can be typed
 * instead for a named campaign.
 *
 * Everything here is bookkeeping. Nothing in this tab, and nothing behind it,
 * creates or edits anything in Stripe: the discount a code unlocks is an existing
 * coupon referenced by `STRIPE_REFERRAL_COUPON_ID`.
 */

interface ReferralCodeRow {
  id: string;
  code: string;
  label: string | null;
  rewardKind: string;
  rewardValue: number | null;
  expiresAt: string | null;
  disabled: boolean;
  createdAt: string;
  redemption: {
    status: string;
    reservedAt: string;
    confirmedAt: string | null;
    stripeSessionId: string | null;
    user: { id: string; email: string; name: string | null };
  } | null;
}

type CodeStatus = "Active" | "Disabled" | "Redeemed" | "Expired";

const STATUS_BADGE: Record<CodeStatus, "success" | "secondary" | "pro" | "warning"> = {
  Active: "success",
  Redeemed: "pro",
  Disabled: "secondary",
  Expired: "warning",
};

/**
 * A code has exactly one status for display purposes. Order matters: a redeemed
 * code stays "Redeemed" even after it is disabled, because that is the fact the
 * operator cares about.
 */
function codeStatus(row: ReferralCodeRow): CodeStatus {
  if (row.redemption) return "Redeemed";
  if (row.disabled) return "Disabled";
  if (row.expiresAt && new Date(row.expiresAt).getTime() <= Date.now()) return "Expired";
  return "Active";
}

const inputClass =
  "w-full h-9 px-3 rounded-lg border border-border text-sm focus:outline-none focus:ring-2 focus:ring-primary-400";

export function ReferralCodesTab() {
  const [rows, setRows] = useState<ReferralCodeRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Create form
  const [label, setLabel] = useState("");
  const [customCode, setCustomCode] = useState("");
  const [expiresOn, setExpiresOn] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/admin/referral-codes", { cache: "no-store" });
      if (!res.ok) {
        setError("Could not load referral codes.");
        return;
      }
      const data = (await res.json()) as ReferralCodeRow[];
      setRows(Array.isArray(data) ? data : []);
    } catch {
      setError("Could not load referral codes.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  /** A `<input type="date">` yields `YYYY-MM-DD`; the API wants an ISO instant. */
  function expiryIso(value: string): string | null {
    if (!value) return null;
    const parsed = new Date(`${value}T23:59:59.000Z`);
    return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
  }

  async function createCode(mode: "generate" | "custom") {
    setBusy(mode);
    setError(null);
    setNotice(null);
    try {
      const body =
        mode === "generate"
          ? {}
          : {
              code: customCode.trim() || undefined,
              label: label.trim() || undefined,
              expiresAt: expiryIso(expiresOn),
            };

      const res = await fetch("/api/admin/referral-codes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const data = (await res.json()) as { code?: string; error?: string };

      if (!res.ok) {
        setError(data.error || "Could not create the code.");
        return;
      }

      setNotice(`Created ${data.code ?? "a new code"}.`);
      if (mode === "custom") {
        setLabel("");
        setCustomCode("");
        setExpiresOn("");
      }
      await load();
    } catch {
      setError("Could not create the code.");
    } finally {
      setBusy(null);
    }
  }

  async function toggleDisabled(row: ReferralCodeRow) {
    setBusy(row.id);
    setError(null);
    setNotice(null);
    try {
      const res = await fetch(`/api/admin/referral-codes/${row.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ disabled: !row.disabled }),
      });
      const data = (await res.json()) as { error?: string };
      if (!res.ok) {
        setError(data.error || "Could not update the code.");
        return;
      }
      await load();
    } catch {
      setError("Could not update the code.");
    } finally {
      setBusy(null);
    }
  }

  async function removeCode(row: ReferralCodeRow) {
    if (!window.confirm(`Delete ${row.code}? This cannot be undone.`)) return;
    setBusy(row.id);
    setError(null);
    setNotice(null);
    try {
      const res = await fetch(`/api/admin/referral-codes/${row.id}`, { method: "DELETE" });
      const data = (await res.json()) as { error?: string };
      if (!res.ok) {
        // Deleting a redeemed code is refused on purpose (audit trail).
        setError(data.error || "Could not delete the code.");
        return;
      }
      setNotice(`Deleted ${row.code}.`);
      await load();
    } catch {
      setError("Could not delete the code.");
    } finally {
      setBusy(null);
    }
  }

  async function copyCode(row: ReferralCodeRow) {
    try {
      await navigator.clipboard.writeText(row.code);
      setCopiedId(row.id);
      window.setTimeout(() => setCopiedId((current) => (current === row.id ? null : current)), 1500);
    } catch {
      setError("Could not copy to the clipboard.");
    }
  }

  return (
    <div className="space-y-4">
      {/* ── Create ─────────────────────────────────────────────────────────── */}
      <div className="bg-white rounded-xl border border-border p-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <p className="text-sm font-semibold text-gray-900">Referral codes</p>
            <p className="text-xs text-muted-fg">
              Each code is single-use, and a member can redeem at most one code ever.
              University and corporate email domains are eligible.
            </p>
          </div>
          <Button size="sm" onClick={() => void createCode("generate")} loading={busy === "generate"}>
            <Tag className="w-4 h-4" /> Generate code
          </Button>
        </div>

        <div className="mt-4 grid gap-3 sm:grid-cols-3">
          <label className="block">
            <span className="mb-1 block text-xs font-semibold text-muted-fg">Label (internal)</span>
            <input
              type="text"
              value={label}
              onChange={(event) => setLabel(event.target.value)}
              placeholder="NUS career fair"
              className={inputClass}
            />
          </label>
          <label className="block">
            <span className="mb-1 block text-xs font-semibold text-muted-fg">
              Custom code (optional)
            </span>
            <input
              type="text"
              value={customCode}
              onChange={(event) => setCustomCode(event.target.value.toUpperCase())}
              placeholder="Leave blank to generate"
              className={`${inputClass} font-mono`}
            />
          </label>
          <label className="block">
            <span className="mb-1 block text-xs font-semibold text-muted-fg">Expires (optional)</span>
            <input
              type="date"
              value={expiresOn}
              onChange={(event) => setExpiresOn(event.target.value)}
              className={inputClass}
            />
          </label>
        </div>

        <div className="mt-3 flex items-center gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => void createCode("custom")}
            loading={busy === "custom"}
            disabled={!label.trim() && !customCode.trim() && !expiresOn}
          >
            Create with these details
          </Button>
          <Button size="sm" variant="ghost" onClick={() => void load()} disabled={loading}>
            <RefreshCw className="w-4 h-4" /> Refresh
          </Button>
        </div>

        {error && <p className="mt-3 text-sm text-red-600">{error}</p>}
        {notice && <p className="mt-3 text-sm text-green-700">{notice}</p>}
      </div>

      {/* ── List ───────────────────────────────────────────────────────────── */}
      <div className="bg-white rounded-xl border border-border overflow-hidden">
        <div className="px-4 py-3 border-b border-border bg-secondary">
          <p className="text-sm text-muted-fg">
            {loading
              ? "Loading referral codes…"
              : `${rows.length} code${rows.length === 1 ? "" : "s"}. Labels are internal and never shown to members.`}
          </p>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[860px]">
            <thead>
              <tr className="border-b border-border bg-secondary text-left">
                <th className="px-4 py-3 font-semibold text-muted-fg">Code</th>
                <th className="px-4 py-3 font-semibold text-muted-fg">Label</th>
                <th className="px-4 py-3 font-semibold text-muted-fg">Status</th>
                <th className="px-4 py-3 font-semibold text-muted-fg">Redeemed by</th>
                <th className="px-4 py-3 font-semibold text-muted-fg">Expires</th>
                <th className="px-4 py-3 font-semibold text-muted-fg">Created</th>
                <th className="px-4 py-3 font-semibold text-muted-fg" />
              </tr>
            </thead>
            <tbody>
              {rows.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-8 text-center text-muted-fg">
                    {loading ? "Loading…" : "No referral codes yet. Generate one to get started."}
                  </td>
                </tr>
              ) : (
                rows.map((row) => {
                  const status = codeStatus(row);
                  return (
                    <tr key={row.id} className="border-b border-border">
                      <td className="px-4 py-3">
                        <span className="font-mono text-xs font-semibold text-gray-900">
                          {row.code}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-xs text-muted-fg">{row.label || "—"}</td>
                      <td className="px-4 py-3">
                        <Badge variant={STATUS_BADGE[status]} size="sm">
                          {status}
                        </Badge>
                      </td>
                      <td className="px-4 py-3 text-xs">
                        {row.redemption ? (
                          <>
                            <p className="text-gray-900">{row.redemption.user.email}</p>
                            <p className="text-muted-fg">
                              {row.redemption.status === "CONFIRMED" ? "Confirmed" : "Reserved"}
                              {row.redemption.confirmedAt
                                ? ` · ${formatDate(row.redemption.confirmedAt)}`
                                : ` · ${formatDate(row.redemption.reservedAt)}`}
                            </p>
                          </>
                        ) : (
                          <span className="text-muted-fg">—</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-xs text-muted-fg">
                        {row.expiresAt ? formatDate(row.expiresAt) : "—"}
                      </td>
                      <td className="px-4 py-3 text-xs text-muted-fg">{formatDate(row.createdAt)}</td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => void copyCode(row)}
                            title="Copy code"
                          >
                            {copiedId === row.id ? (
                              <Check className="w-3.5 h-3.5" />
                            ) : (
                              <Copy className="w-3.5 h-3.5" />
                            )}
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => void toggleDisabled(row)}
                            loading={busy === row.id}
                          >
                            {row.disabled ? "Enable" : "Disable"}
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => void removeCode(row)}
                            title={
                              row.redemption
                                ? "Redeemed codes cannot be deleted (audit trail)"
                                : "Delete code"
                            }
                            disabled={Boolean(row.redemption)}
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
